package com.example.sellcob1;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point for the SELLCOB1 Spring Boot application.
 *
 * <p>Migrated from COBOL CICS program SELLCOB1 (COBOL-AIRLINES project).
 * Original purpose: search a flight and a passenger in order to initiate
 * an airline ticket sale.
 */
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

