package com.example.sellcob1.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * JPA entity representing a row in the PASSENGERS DB2/PostgreSQL table.
 *
 * <p>Corresponds to the EXEC SQL INCLUDE PASSENG copybook used in SELLCOB1.
 */
@Entity
@Table(name = "passengers")
public class Passenger {

    /** CLIENTID  PIC 9(6) – primary key. */
    @Id
    @Column(name = "clientid", nullable = false)
    private Long clientId;

    /** FIRSTNAME – passenger first name. */
    @Column(name = "firstname", length = 50)
    private String firstName;

    /** LASTNAME – passenger last name. */
    @Column(name = "lastname", length = 50)
    private String lastName;

    // ----------------------------------------------------------------
    // Constructors
    // ----------------------------------------------------------------

    protected Passenger() {}

    public Passenger(Long clientId, String firstName, String lastName) {
        this.clientId = clientId;
        this.firstName = firstName;
        this.lastName = lastName;
    }

    // ----------------------------------------------------------------
    // Getters
    // ----------------------------------------------------------------

    public Long getClientId() {
        return clientId;
    }

    public String getFirstName() {
        return firstName;
    }

    public String getLastName() {
        return lastName;
    }
}

