package com.example.sellcob1.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * JPA entity representing a row in the FLIGHT DB2/PostgreSQL table.
 *
 * <p>Corresponds to the EXEC SQL INCLUDE FLIGHT copybook used in SELLCOB1.
 */
@Entity
@Table(name = "flight")
public class Flight {

    /** FLIGHTID  PIC 9(9) – primary key. */
    @Id
    @Column(name = "flightid", nullable = false)
    private Long flightId;

    /** FLIGHTNUM PIC X(6). */
    @Column(name = "flightnum", length = 6, nullable = false)
    private String flightNum;

    /** FLIGHTDATE PIC X(10)  – stored as VARCHAR in the form YYYY-MM-DD. */
    @Column(name = "flightdate", length = 10, nullable = false)
    private String flightDate;

    /** DEPTIME – departure time. */
    @Column(name = "deptime", length = 8)
    private String depTime;

    /** ARRTIME – arrival time. */
    @Column(name = "arrtime", length = 8)
    private String arrTime;

    /** AIRPORTDEP PIC X(3). */
    @Column(name = "airportdep", length = 3)
    private String airportDep;

    /** AIRPORTARR PIC X(3). */
    @Column(name = "airportarr", length = 3)
    private String airportArr;

    // ----------------------------------------------------------------
    // Constructors
    // ----------------------------------------------------------------

    protected Flight() {}

    public Flight(Long flightId, String flightNum, String flightDate,
                  String depTime, String arrTime,
                  String airportDep, String airportArr) {
        this.flightId   = flightId;
        this.flightNum  = flightNum;
        this.flightDate = flightDate;
        this.depTime    = depTime;
        this.arrTime    = arrTime;
        this.airportDep = airportDep;
        this.airportArr = airportArr;
    }

    // ----------------------------------------------------------------
    // Getters
    // ----------------------------------------------------------------

    public Long getFlightId()    { return flightId;   }
    public String getFlightNum() { return flightNum;  }
    public String getFlightDate(){ return flightDate; }
    public String getDepTime()   { return depTime;    }
    public String getArrTime()   { return arrTime;    }
    public String getAirportDep(){ return airportDep; }
    public String getAirportArr(){ return airportArr; }
}

