package com.example.sellcob1.repository;

import com.example.sellcob1.model.Flight;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * Spring Data JPA repository for the FLIGHT table.
 *
 * <p>Replaces the DB2 {@code SELECT FLIGHTID, DEPTIME, ARRTIME, AIRPORTDEP,
 * AIRPORTARR FROM FLIGHT WHERE FLIGHTDATE = :FLIGHTDATE AND FLIGHTNUM = :FLIGHTNUM}
 * statement in SELLCOB1.
 */
@Repository
public interface FlightRepository extends JpaRepository<Flight, Long> {

    /**
     * Finds a flight by its number and date.
     *
     * @param flightNum  the flight number (PIC X(6))
     * @param flightDate the flight date in YYYY-MM-DD format (PIC X(10))
     * @return an {@link Optional} containing the matching flight, if found
     */
    @Query("SELECT f FROM Flight f WHERE f.flightNum = :flightNum AND f.flightDate = :flightDate")
    Optional<Flight> findByFlightNumAndFlightDate(
            @Param("flightNum")  String flightNum,
            @Param("flightDate") String flightDate);
}

