package com.example.sellcob1.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;

/**
 * DTO carrying the input parameters that the user submits on the SELLMP screen.
 *
 * <p>Maps directly to the CICS map fields:
 * <ul>
 *   <li>CLIIDI  – clientId</li>
 *   <li>FNUMI   – flightNum</li>
 *   <li>FDATEI  – flightDate (YYYY-MM-DD)</li>
 *   <li>PASSNI  – numberOfPassengers</li>
 * </ul>
 *
 * <p>Validation replicates the 0610-VERIFY-SPACE paragraph in the COBOL source.
 */
public record SellSearchRequest(

        /** CLIIDI – PIC 9(6). Must be numeric and non-zero. */
        @NotNull(message = "YOU MUST INSERT A NUMBER IN THE CLIENTID")
        @Positive(message = "YOU MUST INSERT A NUMBER IN THE CLIENTID")
        Long clientId,

        /** FNUMI – PIC X(6). Must not be blank. */
        @NotBlank(message = "YOU MUST INSERT A CORRECT FIGHT NUMBER")
        String flightNum,

        /**
         * FDATEI – PIC X(10). Must match YYYY-MM-DD.
         * Mirrors the COBOL check:
         *   FDATEO(1:4) IS NOT NUMERIC OR FDATEO(6:2) IS NOT NUMERIC
         *   OR FDATEO(9:2) IS NOT NUMERIC OR FFDATEO(5:1) NOT = '-'
         *   OR FDATEO(8:1) NOT = '-'
         */
        @NotBlank(message = "THE CORRECT DATA FORMAT IS: YYYY-MM-DD")
        @Pattern(
                regexp = "\\d{4}-\\d{2}-\\d{2}",
                message = "THE CORRECT DATA FORMAT IS: YYYY-MM-DD"
        )
        String flightDate,

        /** PASSNI – PIC 9(1). Must be numeric and non-zero. */
        @NotNull(message = "YOU MUST INSERT A NUMBER IN THE NUMBER OF CLIENTS")
        @Min(value = 1, message = "YOU MUST INSERT A NUMBER IN THE NUMBER OF CLIENTS")
        Integer numberOfPassengers
) {}

