package com.example.sellcob1.dto;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * DTO returned by the sell-search endpoint, mirroring the output fields
 * that SELLCOB1 would populate on the SELLMP map before calling SELLCOB2.
 *
 * <p>Fields:
 * <ul>
 *   <li>flightId        – FLIGHTID   (WS-FLIGHTID / COMM-FLIGHTID)</li>
 *   <li>flightNum       – SFNUMO</li>
 *   <li>flightDate      – SFDATEO</li>
 *   <li>depTime         – SDTIMEO</li>
 *   <li>arrTime         – SLTIMEO</li>
 *   <li>airportDep      – SDAIRO</li>
 *   <li>airportArr      – SLAIRO</li>
 *   <li>passengerFirstName / passengerLastName – from PASSENGERS table</li>
 *   <li>unitPrice       – SPRICEO  (EDIT-PRICE1 formatted)</li>
 *   <li>totalPrice      – STPRICEO (EDIT-PRICE  formatted)</li>
 *   <li>serverDateTime  – LHOURO / LDATEO (server timestamp)</li>
 *   <li>readyForSale    – WS-FLAG-MOUV = 'Y'</li>
 * </ul>
 */
public record SellSearchResponse(
        Long        flightId,
        String      flightNum,
        String      flightDate,
        String      depTime,
        String      arrTime,
        String      airportDep,
        String      airportArr,
        Long        clientId,
        String      passengerFirstName,
        String      passengerLastName,
        int         numberOfPassengers,
        BigDecimal  unitPrice,
        BigDecimal  totalPrice,
        LocalDateTime serverDateTime,
        boolean     readyForSale
) {}

