package com.example.sellcob1.dto;

import java.time.LocalDateTime;
import java.util.List;

/**
 * Uniform error envelope returned by the global exception handler.
 */
public record ErrorResponse(
        int            status,
        String         message,
        List<String>   details,
        LocalDateTime  timestamp
) {
    /** Convenience factory for a single-message error. */
    public static ErrorResponse of(int status, String message) {
        return new ErrorResponse(status, message, List.of(), LocalDateTime.now());
    }

    /** Convenience factory with a detail list. */
    public static ErrorResponse of(int status, String message, List<String> details) {
        return new ErrorResponse(status, message, details, LocalDateTime.now());
    }
}

