package com.example.sellcob1.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Configuration;

import java.math.BigDecimal;

/**
 * Binds application-level configuration from {@code application.properties}.
 *
 * <p>The base ticket price mirrors the hard-coded value {@code 120.99}
 * ({@code MOVE 120.99 TO WS-PRICEV}) in the COBOL program.  Externalising
 * it allows price changes without recompilation.
 */
@Configuration
public class AppProperties {

    private final BigDecimal baseTicketPrice;

    public AppProperties(
            @Value("${app.ticket.base-price:120.99}") BigDecimal baseTicketPrice) {
        this.baseTicketPrice = baseTicketPrice;
    }

    /**
     * Returns the per-seat ticket price (mirrors WS-PRICEV = 120.99 in COBOL).
     *
     * @return unit ticket price
     */
    public BigDecimal getBaseTicketPrice() {
        return baseTicketPrice;
    }
}

// === FILE: src/main/java/com/example/sellcob1/service/SellSearchService.java ===
package com.example.sellcob1.service;

import com.example.sellcob1.config.AppProperties;
import com.example.sellcob1.dto.SellSearchRequest;
import com.example.sellcob1.dto.SellSearchResponse;
import com.example.sellcob1.model.Flight;
import com.example.sellcob1.model.Passenger;
import com.example.sellcob1.repository.FlightRepository;
import com.example.sellcob1.repository.PassengerRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Optional;

/**
 * Core business logic migrated from COBOL program SELLCOB1.
 *
 * <p>Paragraph mapping:
 * <table border="1">
 *   <tr><th>COBOL Paragraph</th><th>Java Method</th></tr>
 *   <tr><td>0600-PROCESS-DATA</td><td>{@link #processData}</td></tr>
 *   <tr><td>0610-VERIFY-SPACE</td><td>Handled via Bean Validation in the controller layer</td></tr>
 *   <tr><td>0210-GIVING-TIME</td><td>{@link #adjustHour}</td></tr>
 *   <tr><td>Price computation (COMPUTE WS-TOTPRICE)</td><td>{@link #computeTotalPrice}</td></tr>
 * </table>
 */
@Service
@Transactional(readOnly = true)
public class SellSearchService {

    private static final Logger log = LoggerFactory.getLogger(SellSearchService.class);

    private final PassengerRepository passengerRepository;
    private final FlightRepository    flightRepository;
    private final AppProperties       appProperties;

    public SellSearchService(
            PassengerRepository passengerRepository,
            FlightRepository    flightRepository,
            AppProperties       appProperties) {
        this.passengerRepository = passengerRepository;
        this.flightRepository    = flightRepository;
        this.appProperties       = appProperties;
    }

    // ----------------------------------------------------------------
    // Public API
    // ----------------------------------------------------------------

    /**
     * Searches for a passenger and a flight, then computes pricing.
     *
     * <p>Faithfully reproduces the logic of {@code 0600-PROCESS-DATA}:
     * <ol>
     *   <li>Look up passenger by clientId – mirrors
     *       {@code SELECT FIRSTNAME, LASTNAME FROM PASSENGERS WHERE CLIENTID = :PA-CLIENTID}.</li>
     *   <li>If found, look up flight by flightNum + flightDate – mirrors
     *       {@code SELECT FLIGHTID, DEPTIME, ARRTIME, AIRPORTDEP, AIRPORTARR
     *       FROM FLIGHT WHERE FLIGHTDATE = :FLIGHTDATE AND FLIGHTNUM = :FLIGHTNUM}.</li>
     *   <li>If both found, compute unit price and total price and set
     *       {@code readyForSale = true} (mirrors {@code MOVE 'Y' TO WS-FLAG-MOUV}).</li>
     * </ol>
     *
     * @param request validated sell-search input
     * @return a fully populated {@link SellSearchResponse}
     * @throws PassengerNotFoundException if SQLCODE 100 for passengers
     * @throws FlightNotFoundException    if SQLCODE 100 for flights
     */
    public SellSearchResponse processData(SellSearchRequest request) {

        log.info("Processing sell search: clientId={}, flightNum={}, flightDate={}, passengers={}",
                request.clientId(), request.flightNum(),
                request.flightDate(), request.numberOfPassengers());

        // ----------------------------------------------------------
        // Step 1 – Find passenger (mirrors the first EXEC SQL SELECT)
        // ----------------------------------------------------------
        Optional<Passenger> passengerOpt =
                passengerRepository.findById(request.clientId());

        if (passengerOpt.isEmpty()) {
            // Mirrors: MOVE 'THIS PASSENGER DOES NOT EXIST' TO MSG1O
            //          MOVE 'N' TO WS-FLAG-MOUV
            throw new PassengerNotFoundException(
                    "THIS PASSENGER DOES NOT EXIST", request.clientId());
        }

        Passenger passenger = passengerOpt.get();

        // ----------------------------------------------------------
        // Step 2 – Find flight (mirrors the second EXEC SQL SELECT)
        // ----------------------------------------------------------
        Optional<Flight> flightOpt =
                flightRepository.findByFlightNumAndFlightDate(
                        request.flightNum().trim(), request.flightDate());

        if (flightOpt.isEmpty()) {
            // Mirrors: MOVE 'THIS FLIGHT DOES NOT EXIST' TO MSG1O
            //          MOVE 'N' TO WS-FLAG-MOUV
            throw new FlightNotFoundException(
                    "THIS FLIGHT DOES NOT EXIST",
                    request.flightNum(), request.flightDate());
        }

        Flight flight = flightOpt.get();

        // ----------------------------------------------------------
        // Step 3 – Price calculation
        // Mirrors:
        //   MOVE 120.99 TO WS-PRICEV
        //   COMPUTE WS-TOTPRICE = WS-PRICEV * PASSNI
        // ----------------------------------------------------------
        BigDecimal unitPrice  = appProperties.getBaseTicketPrice();
        BigDecimal totalPrice = computeTotalPrice(unitPrice, request.numberOfPassengers());

        // ----------------------------------------------------------
        // Step 4 – Build response (mirrors MOVEs to map output fields)
        // readyForSale = true mirrors: MOVE 'Y' TO WS-FLAG-MOUV
        // ----------------------------------------------------------
        LocalDateTime serverDateTime = buildServerDateTime();

        return new SellSearchResponse(
                flight.getFlightId(),
                flight.getFlightNum(),
                flight.getFlightDate(),
                flight.getDepTime(),
                flight.getArrTime(),
                flight.getAirportDep(),
                flight.getAirportArr(),
                passenger.getClientId(),
                passenger.getFirstName(),
                passenger.getLastName(),
                request.numberOfPassengers(),
                unitPrice,
                totalPrice,
                serverDateTime,
                true   // WS-FLAG-MOUV = 'Y'
        );
    }

    // ----------------------------------------------------------------
    // Private helpers
    // ----------------------------------------------------------------

    /**
     * Computes the total ticket price.
     *
     * <p>Mirrors: {@code COMPUTE WS-TOTPRICE = WS-PRICEV * PASSNI}
     *
     * @param unitPrice          price per seat
     * @param numberOfPassengers number of seats
     * @return total price
     */
    private BigDecimal computeTotalPrice(BigDecimal unitPrice, int numberOfPassengers) {
        return unitPrice.multiply(BigDecimal.valueOf(numberOfPassengers));
    }

    /**
     * Returns the current server date/time, adjusted by the same +1 hour
     * rule as the COBOL {@code 0210-GIVING-TIME} paragraph:
     *
     * <pre>
     *   IF WS-HOUR = 23
     *      MOVE ZEROS TO WS-HOUR
     *   ELSE
     *      ADD 1 TO WS-HOUR.
     * </pre>
     *
     * @return adjusted server {@link LocalDateTime}
     */
    private LocalDateTime buildServerDateTime() {
        LocalDateTime now = LocalDateTime.now();
        int adjustedHour  = adjustHour(now.getHour());
        return now.withHour(adjustedHour);
    }

    /**
     * Mirrors the 0210-GIVING-TIME COBOL logic:
     * if hour == 23 reset to 0, otherwise increment by 1.
     *
     * @param currentHour the raw hour (0-23)
     * @return the adjusted hour
     */
    int adjustHour(int currentHour) {
        return (currentHour == 23) ? 0 : currentHour + 1;
    }

    // ----------------------------------------------------------------
    // Domain exceptions (inner classes – keep everything cohesive)
    // ----------------------------------------------------------------

    /**
     * Thrown when SQLCODE 100 is returned for the PASSENGERS query.
     * Mirrors: {@code MOVE 'THIS PASSENGER DOES NOT EXIST' TO MSG1O}.
     */
    public static class PassengerNotFoundException extends RuntimeException {
        private final long clientId;

        public PassengerNotFoundException(String message, long clientId) {
            super(message);
            this.clientId = clientId;
        }

        public long getClientId() { return clientId; }
    }

    /**
     * Thrown when SQLCODE 100 is returned for the FLIGHT query.
     * Mirrors: {@code MOVE 'THIS FLIGHT DOES NOT EXIST' TO MSG1O}.
     */
    public static class FlightNotFoundException extends RuntimeException {
        private final String flightNum;
        private final String flightDate;

        public FlightNotFoundException(String message,
                                       String flightNum, String flightDate) {
            super(message);
            this.flightNum  = flightNum;
            this.flightDate = flightDate;
        }

        public String getFlightNum()  { return flightNum;  }
        public String getFlightDate() { return flightDate; }
    }
}

