package com.example.sellcob1.controller;

import com.example.sellcob1.dto.SellSearchRequest;
import com.example.sellcob1.dto.SellSearchResponse;
import com.example.sellcob1.service.SellSearchService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST controller that exposes the sell-search workflow of COBOL program SELLCOB1.
 *
 * <h2>Endpoint</h2>
 * <pre>
 *   POST /api/sell/search
 *   Content-Type: application/json
 * </pre>
 *
 * <h2>Business flow</h2>
 * The controller corresponds to the {@code MAIN-PARA} pseudo-conversational
 * flow of SELLCOB1 when {@code EIBCALEN > 0} and the user has submitted data
 * (i.e., the RECEIVE-MAP + PROCESS-DATA path):
 * <ol>
 *   <li>Validate input – mirrors {@code 0610-VERIFY-SPACE}.</li>
 *   <li>Delegate to {@link SellSearchService#processData} – mirrors
 *       {@code 0600-PROCESS-DATA}.</li>
 *   <li>Return the populated response – mirrors the MAP output fields that
 *       would be passed to SELLCOB2 via COMMAREA.</li>
 * </ol>
 */
@RestController
@RequestMapping("/api/sell")
public class SellSearchController {

    private final SellSearchService sellSearchService;

    public SellSearchController(SellSearchService sellSearchService) {
        this.sellSearchService = sellSearchService;
    }

    /**
     * Searches for a passenger and a flight and returns pricing information.
     *
     * <p>A {@code 200 OK} response with {@code readyForSale=true} means the
     * client may proceed to the confirmation step (equivalent to pressing PF12
     * to invoke SELLCOB2 in the original CICS flow).
     *
     * @param request the sell-search parameters (validated)
     * @return {@link ResponseEntity} wrapping a {@link SellSearchResponse}
     */
    @PostMapping("/search")
    public ResponseEntity<SellSearchResponse> search(
            @Valid @RequestBody SellSearchRequest request) {

        SellSearchResponse response = sellSearchService.processData(request);
        return ResponseEntity.status(HttpStatus.OK).body(response);
    }
}

