package com.example.sellcob1.config;

import com.example.sellcob1.dto.ErrorResponse;
import com.example.sellcob1.service.SellSearchService.FlightNotFoundException;
import com.example.sellcob1.service.SellSearchService.PassengerNotFoundException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.List;

/**
 * Global exception handler that translates domain and validation exceptions
 * into consistent HTTP responses.
 *
 * <p>Error messages intentionally mirror the MSG1O / MSG2O strings that
 * SELLCOB1 would display on the CICS map.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /**
     * Handles Bean Validation failures from {@code @Valid} on the controller.
     *
     * <p>Mirrors: the 0610-VERIFY-SPACE paragraph – each field message
     * matches the COBOL MOVE ... TO MSG1O statement for that field.
     *
     * @param ex the validation exception
     * @return 400 Bad Request with all field messages
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorResponse> handleValidation(
            MethodArgumentNotValidException ex) {

        List<String> details = ex.getBindingResult()
                .getFieldErrors()
                .stream()
                .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
                .toList();

        log.warn("Validation failed: {}", details);

        return ResponseEntity
                .status(HttpStatus.BAD_REQUEST)
                .body(ErrorResponse.of(400,
                        "Input validation failed – check field details.", details));
    }

    /**
     * Handles a missing passenger.
     *
     * <p>Mirrors: {@code MOVE 'THIS PASSENGER DOES NOT EXIST' TO MSG1O}
     *             (SQLCODE 100 branch for the PASSENGERS SELECT).
     *
     * @param ex the not-found exception
     * @return 404 Not Found
     */
    @ExceptionHandler(PassengerNotFoundException.class)
    public ResponseEntity<ErrorResponse> handlePassengerNotFound(
            PassengerNotFoundException ex) {

        log.warn("Passenger not found: clientId={}", ex.getClientId());

        return ResponseEntity
                .status(HttpStatus.NOT_FOUND)
                .body(ErrorResponse.of(404, ex.getMessage()));
    }

    /**
     * Handles a missing flight.
     *
     * <p>Mirrors: {@code MOVE 'THIS FLIGHT DOES NOT EXIST' TO MSG1O}
     *             (SQLCODE 100 branch for the FLIGHT SELECT).
     *
     * @param ex the not-found exception
     * @return 404 Not Found
     */
    @ExceptionHandler(FlightNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleFlightNotFound(
            FlightNotFoundException ex) {

        log.warn("Flight not found: flightNum={}, flightDate={}",
                ex.getFlightNum(), ex.getFlightDate());

        return ResponseEntity
                .status(HttpStatus.NOT_FOUND)
                .body(ErrorResponse.of(404, ex.getMessage()));
    }

    /**
     * Catch-all for unexpected errors.
     *
     * <p>Mirrors the COBOL WHEN OTHER branch:
     * {@code MOVE 'THERE WAS A ERROR IN THE RESEARCH PROCESS' TO MSG1O}
     * {@code MOVE 'CONTACT THE IT DEPARTEMENT AND INFORM THIS CODE:' TO MSG2O}
     *
     * @param ex any unhandled exception
     * @return 500 Internal Server Error
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGeneric(Exception ex) {

        log.error("Unexpected error in sell-search processing", ex);

        return ResponseEntity
                .status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(ErrorResponse.of(
                        500,
                        "THERE WAS A ERROR IN THE RESEARCH PROCESS",
                        List.of(
                                "CONTACT THE IT DEPARTEMENT AND INFORM THIS CODE:",
                                ex.getClass().getSimpleName() + ": " + ex.getMessage()
                        )
                ));
    }
}
